changeSet.sql:
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
          FROM pg_trigger
         WHERE tgname = 'trg_rollback_audit_no_truncate'
           AND tgrelid = 'rollback_audit_log'::regclass
           AND NOT tgisinternal
    ) THEN
        CREATE TRIGGER trg_rollback_audit_no_truncate
        BEFORE TRUNCATE ON rollback_audit_log
        FOR EACH STATEMENT EXECUTE FUNCTION dts_reject_rollback_evidence_mutation();
    END IF;

    IF NOT EXISTS (
        SELECT 1
          FROM pg_trigger
         WHERE tgname = 'trg_ingestion_rollback_evidence_no_truncate'
           AND tgrelid = 'ingestion_rollback_affected_object'::regclass
           AND NOT tgisinternal
    ) THEN
        CREATE TRIGGER trg_ingestion_rollback_evidence_no_truncate
        BEFORE TRUNCATE ON ingestion_rollback_affected_object
        FOR EACH STATEMENT EXECUTE FUNCTION dts_reject_rollback_evidence_mutation();
    END IF;
END;
$$;

rollback.sql:
DO $$
BEGIN
    RAISE EXCEPTION 'ROLLBACK_BLOCKED_INGESTION_ROLLBACK_TRUNCATE_GUARDS_FORWARD_ONLY: recovery requires a new forward changeset';
END $$;
